begin;
select plan(23);

select is((public.qnotes_create_note((select id from auth.users where email = 'owner@qnotes.local'), '44444444-4444-4444-8444-444444444444', 'search-owner-a', 'Search Owner A', '# Search Owner A\n\nQuadrate attachment search marker 8241', 'Search Owner A Quadrate attachment search marker 8241', '{}', '44444444-4444-4444-8444-444444444445', '44444444-4444-4444-8444-444444444446', 'search-hash-a', '[{"blockKey":"deploy-key","blockType":"command","title":"Deploy","language":"bash","content":"docker deploy marker 8241","position":0,"copyable":true,"contentHash":"search-block-hash"}]'::jsonb, '[{"sourceType":"note_chunk","sourceKey":"search-note","sourceTitle":"Search Owner A","headingPath":"Search Owner A","content":"Quadrate attachment search marker 8241","contentHash":"search-note-hash","position":0},{"sourceType":"copy_block","sourceKey":"deploy-key","sourceTitle":"Deploy","headingPath":null,"content":"docker deploy marker 8241","contentHash":"search-block-hash","position":1}]'::jsonb)->>'status'), 'ok', 'search fixture note is committed');
select ok((select count(*) = 1 from notesdb.search_documents where note_id = '44444444-4444-4444-8444-444444444444' and source_type = 'note_metadata'), 'each note has one metadata search document');
select is((select source_type from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), 'search-owner-a', 20) where note_id = '44444444-4444-4444-8444-444444444444' limit 1), 'note_metadata', 'exact slug matches use the metadata document identity');
select ok((select bool_and(embedding_status = 'pending') from notesdb.search_documents where note_id = '44444444-4444-4444-8444-444444444444'), 'search documents are pending embeddings after save');
select is((public.qnotes_create_note((select id from auth.users where email = 'owner@qnotes.local'), '44444444-4444-4444-8444-444444444460', 'deep-snippet', 'Deep Snippet', 'Deep Snippet', repeat('prefix ', 120) || 'DeepSnippetMarkerZZZ' || repeat(' suffix', 120), '{}', '44444444-4444-4444-8444-444444444461', '44444444-4444-4444-8444-444444444462', 'search-deep-hash', '[]'::jsonb, jsonb_build_array(jsonb_build_object('sourceType', 'note_chunk', 'sourceKey', 'deep-snippet-chunk', 'sourceTitle', 'Deep Snippet', 'headingPath', 'Deep Snippet', 'content', repeat('prefix ', 120) || 'DeepSnippetMarkerZZZ' || repeat(' suffix', 120), 'contentHash', 'search-deep-content-hash', 'position', 0)))->>'status'), 'ok', 'deep snippet fixture is committed');
select ok((select snippet like '%DeepSnippetMarkerZZZ%' from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), 'DeepSnippetMarkerZZZ', 20) where note_id = '44444444-4444-4444-8444-444444444460' limit 1), 'keyword snippets center a deep content match');
select ok((select count(*) > 0 from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', 20)), 'keyword search works before embeddings complete');
select ok((select count(*) > 0 from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), 'deploy-key', 20) where source_type = 'copy_block' and source_key = 'deploy-key'), 'named blocks appear as independent search results');
select is((public.qnotes_create_note((select id from auth.users where email = 'owner@qnotes.local'), '44444444-4444-4444-8444-444444444451', 'priority-title-result', 'Priority Title Result', 'An unrelated body.', 'An unrelated body.', '{}', '44444444-4444-4444-8444-444444444452', '44444444-4444-4444-8444-444444444453', 'search-title-priority-hash', '[]'::jsonb, '[]'::jsonb)->>'status'), 'ok', 'title-priority fixture is committed');
select is((public.qnotes_create_note((select id from auth.users where email = 'owner@qnotes.local'), '44444444-4444-4444-8444-444444444454', 'body-partial-result', 'Unrelated Body Note', 'This body contains priority and SupercalifragPartialNeedle.', 'This body contains priority and SupercalifragPartialNeedle.', '{}', '44444444-4444-4444-8444-444444444455', '44444444-4444-4444-8444-444444444456', 'search-body-partial-hash', '[]'::jsonb, '[]'::jsonb)->>'status'), 'ok', 'body-partial fixture is committed');
select is((select note_id::text from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), 'priority', 20) limit 1), '44444444-4444-4444-8444-444444444451', 'title matches rank before body matches');
select is((select note_id::text from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), 'PartialNeed', 20) limit 1), '44444444-4444-4444-8444-444444444454', 'partial body matches are returned');
select is((public.qnotes_create_note((select id from auth.users where email = 'owner@qnotes.local'), '44444444-4444-4444-8444-444444444457', 'searchable-empty-title', 'Searchable Empty Title', '', '', '{}', '44444444-4444-4444-8444-444444444458', '44444444-4444-4444-8444-444444444459', 'search-empty-title-hash', '[]'::jsonb, '[]'::jsonb)->>'status'), 'ok', 'title-only fixture is committed');
select ok((select count(*) > 0 from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), 'Searchable', 20) where note_id = '44444444-4444-4444-8444-444444444457'), 'title-only notes are searchable');
select is((public.qnotes_create_note((select id from auth.users where email = 'other@qnotes.local'), '44444444-4444-4444-8444-444444444447', 'search-owner-b', 'Search Owner B', 'Quadrate attachment search marker 8241', 'Quadrate attachment search marker 8241', '{}', '44444444-4444-4444-8444-444444444448', '44444444-4444-4444-8444-444444444449', 'search-hash-b', '[]'::jsonb, '[{"sourceType":"note_chunk","sourceKey":"search-note-b","sourceTitle":"Search Owner B","headingPath":null,"content":"Quadrate attachment search marker 8241","contentHash":"search-note-b-hash","position":0}]'::jsonb)->>'status'), 'ok', 'Owner B search fixture note is committed');
select ok((select not exists (select 1 from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', 20) where note_id <> '44444444-4444-4444-8444-444444444444')), 'search never returns another owner record');

update notesdb.search_documents set embedding = ('[' || repeat('0,', 383) || '0]')::extensions.vector, embedding_status = 'ready', embedding_model = 'gte-small', embedding_model_version = 'v1' where note_id = '44444444-4444-4444-8444-444444444444';
select ok((select count(*) > 0 from public.qnotes_semantic_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', ('[' || repeat('0,', 383) || '0]')::extensions.vector, 20)), 'semantic search returns deterministic fake embeddings');
select ok((select count(*) > 0 from public.qnotes_hybrid_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', ('[' || repeat('0,', 383) || '0]')::extensions.vector, 20, 60)), 'hybrid search combines keyword and semantic results');
select ok((select max(note_count) <= 2 from (select note_id, count(*)::integer as note_count from public.qnotes_hybrid_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', ('[' || repeat('0,', 383) || '0]')::extensions.vector, 20, 60) group by note_id) grouped), 'hybrid search returns at most two results per note');
select is((select count(*)::integer from public.qnotes_hybrid_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', ('[' || repeat('0,', 383) || '0]')::extensions.vector, 20, 60)), (select count(distinct id)::integer from public.qnotes_hybrid_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', ('[' || repeat('0,', 383) || '0]')::extensions.vector, 20, 60)), 'hybrid results have distinct document identities');
select ok((select count(*) > 0 from (select id from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', 20)) keyword join (select id from public.qnotes_semantic_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', ('[' || repeat('0,', 383) || '0]')::extensions.vector, 20) semantic using (id)), 'keyword and semantic channels share document IDs');

select is((public.qnotes_soft_delete_note((select id from auth.users where email = 'owner@qnotes.local'), '44444444-4444-4444-8444-444444444444', 1, '44444444-4444-4444-8444-444444444445', '44444444-4444-4444-8444-444444444450', 'search-delete-hash')->>'status'), 'ok', 'search fixture can be soft deleted');
select is((select count(*)::integer from public.qnotes_keyword_search((select id from auth.users where email = 'owner@qnotes.local'), '8241', 20)), 0, 'soft-deleted notes do not appear in keyword search');

select * from finish();
rollback;
